@@ -67,11 +67,10 @@ public abstract class AbstractConstant<T extends AbstractConstant<T>> implements
             return 0;
         }

-        @SuppressWarnings("UnnecessaryLocalVariable")
+        // Access the private 'uniquifier' field through the class type rather than the type variable 'o':
+        // private members are not accessible through a type-variable-typed reference.
         AbstractConstant<T> other = o;
-        int returnCode;
-
-        returnCode = hashCode() - other.hashCode();
+        int returnCode = hashCode() - other.hashCode();
         if (returnCode != 0) {
             return returnCode;
         }
