-        int shortestLength = 0;
+        int longestStart = -1;
+        int longestLength = 0;
         for (int i = 0; i < words.length; ++i) {
             if (words[i] == 0) {
                 if (currentStart < 0) {
@@ -1004,9 +1004,9 @@ public final class NetUtil {
                 }
             } else if (currentStart >= 0) {
                 currentLength = i - currentStart;
-                if (currentLength > shortestLength) {
-                    shortestStart = currentStart;
